usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Videos.List(
		context.TODO(),
		openai.VideoListParams{
			Limit: param.NewOpt[int64](1),
			Order: param.NewOpt[openai.OrderEnum](openai.OrderEnumAsc),
			After: param.NewOpt[string]("after"),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
